      "content": "{\n  \"name\": \"@y9931666/dsh-plugin-crossfire\",\n  \"version\": \"0.1.3\",\n  \"publishConfig\": {\n    \"access\": \"public\",\n    \"registry\": \"https://registry.npmjs.org/\"\n  },\n  \"description\": \"Crossfire (针锋) for DeepSeek Harness: put a settled result on the stand, let red-team experts attack it from chosen dimensions, and adjudicate every single defect yourself. Adversarial review as a first-class primitive — no topology, no aggregation gateway, no automatic fixes. The machine only finds flaws; the human always owns the verdict.\",\n  \"author\": {\n    \"name\": \"y9931666\",\n    \"url\": \"https://github.com/9931666\"\n  },\n  \"homepage\": \"https://github.com/9931666/dsh-plugin-crossfire#readme\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/9931666/dsh-plugin-crossfire.git\"\n  },\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"crossfire\",\n    \"针锋\",\n    \"adversarial-review\",\n    \"red-team\",\n    \"defect-adjudication\"\n  ],\n  \"type\": \"module\",\n  \"license\": \"MIT\",\n  \"main\": \"./lib/index.js\",\n  \"types\": \"./lib/types/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/types/client/index.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"cordis.patch.yml\",\n    \"release-notes\",\n    \"README.md\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-conversation\",\n        \"@deepseek-ai/dsh-client-ui-renderer\",\n        \"@deepseek-ai/dsh-cl