      "path": "src/index.ts",
      "content": "/**\n * Crossfire（针锋）—— host 插件入口。\n *\n * 它是一个**只做对抗式评审**的 host 插件：把一个已定稿的成果摆上台，让红队\n * 专家从指定维度分头攻击，把攻击拆成逐条可裁决的缺陷，由人逐条认定或驳回。\n *\n * 与圆桌会议（`@y9931666/dsh-plugin-roundtable`）的关系：**零代码耦合**。针锋是从\n * 圆桌里长出来的一件东西，但它不 import 圆桌的任何模块、不读圆桌的状态目录、\n * 不改圆桌的任何文件。两者共存的唯一代价是各自维护一份内核。\n *\n * 批 1 交付：插件骨架（Config + 偏好存储 + 一条 RPC web 路由 + 系统提示段）。\n * 批 2 加数据模型与 `crossfire_*` 工具；批 3 加轨迹内卡片；批 4 加立场区与\n * 设置页全量。\n *\n * @module dsh-plugin-crossfire\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport z from '@deepseek-ai/schemastery'\n// Declaration merge only: makes ctx.systemPrompt / ctx.tools / ctx.subagents visible.\nimport type {} from '@deepseek-ai/dsh-system-prompt'\nimport type {} from '@deepseek-ai/dsh-tools'\nimport type {} from '@deepseek-ai/dsh-subagent'\nimport type {} from '@deepseek-ai/dsh-agent'\nimport type { IncomingMessage, ServerResponse } from 'node:http'\nimport { attachExpertEvents } from './expert-events.ts'\nimport { sendJsonConditional } from './etag.ts'\nimport { usageSectionText } from './prompt.ts'\nimport { createPreferenceStore, defaultPreferences, type CrossfirePreferences } from './preferences.ts'\nimport { collectSnapshots, RPC_ROUTE, registerRpc, STATE_ROUTE, type CrossfireRuntime } from './rpc.ts'\nimport { registerCrossfireTools } from './tools.ts'\nimport { fenceProbe, MAX_RPC_BODY_BYTES, rejectWebRequest } from './web-guard.ts'\nimport { WEB_SERVER_KEYS, WORKSPACE_KEYS, effectWithOptionalDisposer, webRouteHostOf } from './harness-compat.ts'\n\n/** 插件名（cordis entry id / 日志前缀 / bundle patch 里的 id）。 */\nexport const name = 'crossfire'\n\n/**\n * REQUIRED services only —— 这份清单是**加载门禁**，所以它必须短。\n *\n * cordis 没有\"可选注入\"这种形式（`Inject` 只有 `string[] | Record`，而 record\n * 形式是拦截配置），因此写在这里的每个名字都会让整个插件 fiber 保持 PENDING\n * 直到该服务存在：没有工具、没有 `/plugins/dsh-plugin-crossfire/*` 路由、没有\n * 卡片、也没有设置页。而缺一个**可选**能力却写在这里，在用户眼里就是\"针锋整个\n * 不见了\"，且任何地方都不报错。\n *\n * 所以 `llm` / `webServer` / `workspaceRegistry` / `connection` 一律**不列**，\n * 全部经 `ctx.get(...)` 或 harness-compat 的探测层懒取：\n *   - `llm` 缺席时，观点拆分退到本地启发式兜底（零 token、确定性）；\n *   - `webServer` 缺席时，只有设置页与卡片失联，host 侧与工具照常工作；\n *   - `connection` 缺席时，RPC 只走插件自有路由。\n */\nexport const inject = ['tools', 'subagents', 'agents', 'systemPrompt']\n\n/** 插件配置。 */\nexport interface Config {\n  /** 评审状态目录名（相对会话工作区，默认 `.crossfire`）。 */\n  stateDir?: string\n  /** `ctx.subagents` 里用于拉起红队专家的 provider（默认 `spawn`）。 */\n  memberProvider?: string\n  /** 一场评审的专家数硬上限（默认 7，与固定维度池同宽）。 */\n  maxExperts?: number\n  /** 默认攻击强度档（默认 `standard`）。 */\n  defaultIntensity?: 'quick' | 'standard' | 'deep'\n  /** 专家子代理的委派深度上限（默认 1：专家不得再招人）。 */\n  memberMaxDepth?: number\n  /** 用法段在全局系统提示里的排序位（默认 117，避开圆桌的 116）。 */\n  promptSectionOrder?: number\n  /**\n   * 专家**继承主持人**时实际生效的模型路由（provider / model）。\n   *\n   * 它只影响可观测性：开打时把这个生效值写回专家记录，卡片才能把\"继承\"画成真实\n   * 品牌（DeepSeek 的蓝色 DS 块），而不是一个中性灰 `?`。取不到时不写，界面会退化成\n   * `?` + `title=\"继承主持人\"`，不会显示一个并非事实的路由。\n   */\n  defaultProvider?: string\n  defaultModel?: string\n}\n\n/**\n * 配置 schema（schemastery）。\n *\n * 刻意**不**写 `: z<Config>` 注解：schemastery 的 `.default()` 会把字段推导成\n * `T | Volatile<T>`（例如 `string | Volatile<string>`），而手写接口写的是\n * `string | undefined`，二者不兼容会让 `tsc --emitDeclarationOnly` 以 TS2322\n * 失败 —— 注意 `--noEmit` **不报**这个错，所以它只在生成声明时暴露。\n * schema 自己就是配置形状的权威来源；下面的 `Config` 接口只用于 `apply` 的签名。\n */\nexport const Config = z.object({\n  stateDir: z.string().default('.crossfire'),\n  memberProvider: z.string().default('spawn'),\n  maxExperts: z.natural().min(1).default(7),\n  defaultIntensity: z.union(['quick', 'standard', 'deep']).default('standard'),\n  memberMaxDepth: z.natural().default(1),\n  // 专家继承主持人时的生效路由（只为把\"继承\"画成真实品牌块，不参与任何路由决策）。\n  //\n  // model 必须与**宿主真实路由同名**：`web` profile 的 agent-default-model 段是\n  // provider `deepseek-official` + model `deepseek-flash`。此前这里写的是\n  // `deepseek-v4-flash`（那是 models 目录里另一个真实存在的 id，也是 collect 拆分用的\n  // 路由），于是继承主持人的专家在卡片上报出一个并非宿主默认值的模型名 —— 一句看起来\n  // 精确、实际不对的显示。**注意不要顺手改 `reviewSplit.model`**：那是观点拆分的真实\n  // 路由，与本字段无关，另有实测依据。\n  defaultProvider: z.string().default('deepseek-official'),\n  defaultModel: z.string().default('deepseek-flash'),\n  promptSectionOrder: z.natural().default(117),\n})\n\nexport function apply(ctx: Context, config: Config): void {\n  const resolved = {\n    stateDir: config.stateDir ?? '.crossfire',\n    memberProvider: config.memberProvider ?? 'spawn',\n    maxExperts: config.maxExperts ?? 7,\n    defaultIntensity: config.defaultIntensity ?? 'standard',\n    memberMaxDepth: config.memberMaxDepth ?? 1,\n    defaultProvider: config.defaultProvider ?? 'deepseek-official',\n    // 与 schema 的默认值**必须同源**：这里是 schema 未生效时（直接调用 apply 的测试、\n    // 或老配置对象）的兜底，两处不同名就会造出\"同一次加载两个模型名\"的裂缝。\n    defaultModel: config.defaultModel ?? 'deepseek-flash',\n  }\n\n  // 用法段进全局系统提示。文本住在 prompt.ts，便于测试断言体积。\n  ctx.systemPrompt.section({\n    name: 'crossfire:usage',\n    order: config.promptSectionOrder ?? 117,\n    text: usageSectionText(),\n  })\n\n  // 偏好存储：插件 Config 是组合基准，用户偏好赢。在工具/路由注册之前创建，\n  // 这样它们的闭包能读到实时值。\n  const prefsStore = createPreferenceStore({\n    base: defaultPreferences(resolved.defaultIntensity),\n    log: (message, error) => {\n      if (error === undefined) ctx.logger.warn(message)\n      else ctx.logger.warn(message, error)\n    },\n  })\n\n  // 工具与浏览器 RPC **共用同一份**运行时配置：两条入口必须驱动同一套状态机\n  // （O1 直推），所以配置只能有一处来源，否则迟早分叉。\n  const runtime: CrossfireRuntime = {\n    prefs: prefsStore,\n    tools: {\n      stateDir: resolved.stateDir,\n      memberProvider: resolved.memberProvider,\n      maxExperts: resolved.maxExperts,\n      // 专家继承主持人时的生效路由：只为把\"继承\"画成真实品牌块（见 members.ts）。\n      defaultProvider: resolved.defaultProvider,\n      defaultModel: resolved.defaultModel,\n      ...(resolved.memberMaxDepth === undefined ? {} : { memberMaxDepth: resolved.memberMaxDepth }),\n      // 观点拆分的 LLM 路由：默认 deepseek-official/deepseek-v4-flash（圆桌实测可用）。\n      // 取不到 llm 服务或该路由不可用时，collect 自动退到本地启发式兜底（零 token、\n      // 确定性），因此这不是加载门禁。批 4 会把它做成设置项。\n      reviewSplit: {\n        provider: 'deepseek-official',\n        model: 'deepseek-v4-flash',\n        maxOpinions: 3,\n      },\n      // 每次调用实时读偏好：改设置对下一场评审立即生效，不需要重启宿主。\n      getDefaults: () => {\n        const prefs = prefsStore.get()\n        return {\n          intensity: prefs.defaultIntensity,\n          maxRounds: prefs.maxRounds,\n          maxTokens: prefs.maxTokens,\n          expertMaxTokens: prefs.expertMaxTokens,\n          expertMaxOpinions: prefs.expertMaxOpinions,\n          customDimensions: prefs.customDimensions,\n        }\n      },\n    },\n  }\n\n  // 偏好里的 defaultIntensity 就是\"设置页那一层\"：用户一改，后续新建评审立即采用。\n  const applyDefaultIntensity = (preference: CrossfirePreferences): void => {\n    if (preference.defaultIntensity === 'quick'\n      || preference.defaultIntensity === 'standard'\n      || preference.defaultIntensity === 'deep') {\n      resolved.defaultIntensity = preference.defaultIntensity\n    }\n  }\n  runtime.prefs.watch(applyDefaultIntensity)\n  // 读盘是异步的：首次加载完成后补同步一次 —— 用户上次选定的强度档不该等到他\n  // 再动一次设置才生效。\n  void runtime.prefs.ready().then(() => {\n    applyDefaultIntensity(runtime.prefs.get())\n  }).catch(() => {\n    // ready() 内部已把读失败降级为默认值，这里无事可做。\n  })\n\n  // 工具面：6 个主持人工具 + 1 个专家工具（crossfire_report）。\n  registerCrossfireTools(ctx, runtime.tools)\n  // 专家产出自动落盘（即使它没调 crossfire_report 或被中断），失败原因写进专家备注。\n  attachExpertEvents(ctx)\n\n  // 同一份 dispatch 会挂到 web 路由上（批 3 起，卡片与工具也会共用它）。\n  const dispatchRpc = registerRpc(ctx, runtime)\n\n  // 宿主的通用 rpc 通道 `/crossfire`。\n  //\n  // 客户端把它当\"自有 web 路由不可达时的降级传输\"（见 client/index.ts 的注释），\n  // 而**这个通道此前从未被注册**：客户端那一行 `connection.rpc.call('/crossfire', …)`\n  // 必然失败、被 catch 吞掉，用户可见行为与\"根本没有兜底\"完全相同；为它写好的\n  // `effectWithOptionalDisposer` 也就成了死代码（红队评审抓出的真实缺陷）。\n  //\n  // 现在真正接上：`connection` 是可选服务（**不列进 inject**，缺席只是少一条传输），\n  // 注册失败/返回非法 disposer 时记一条降级，而不是让插件 PENDING。\n  const crossfireChannel = (ctx.get('connection') as unknown as {\n    rpc?: { handle?: (channel: string, dispatch: unknown) => unknown }\n  } | undefined)?.rpc?.handle\n  if (typeof crossfireChannel === 'function') {\n    const connection = ctx.get('connection') as unknown as {\n      rpc: { handle: (channel: string, dispatch: unknown) => unknown }\n    }\n    const released = effectWithOptionalDisposer(\n      ctx,\n      connection.rpc.handle('/crossfire', (endpoint: string, payload: unknown) => dispatchRpc(endpoint, payload)),\n      'crossfire: rpc channel',\n    )\n    if (!released) {\n      ctx.logger.warn('crossfire: connection.rpc.handle returned no disposer — the fallback channel may leak')\n    }\n  } else {\n    ctx.logger.warn('crossfire: connection.rpc.handle is unavailable — the card will only reach the host over its own web route')\n  }\n\n  // Web 面：设置页与（批 3 起的）卡片都靠它。headless profile 可能根本不挂\n  // web 服务 —— 那就按服务可用性惰性注册，插件其余部分照常工作。\n  let rpcRouteRegistered = false\n  let stateRouteRegistered = false\n  const registerWebSurface = (): void => {\n    const webServer = webRouteHostOf(ctx)\n    if (webServer === undefined) {\n      // 「降级由调用方留痕」：harness-compat 的探测层是零副作用的，所以这里\n      // 必须自己说清楚发生了什么，否则设置页静默打不开而无人能诊断。\n      ctx.logger.warn('crossfire: no web route host available — the settings page will not reach the host')\n      return\n    }\n    // 宿主 webserver 不会自动施加 Host/Origin + 浏览器认证栅栏，必须由路由自己\n    // 调 `connection.requestRejection`。取不到该服务时放行（最小 profile 不能\n    // 因此瘫痪），但只要能取到就一定要用。\n    //\n    // **刻意在每次请求时实时取，而不是在注册时快照一个闭包**（修红队评审抓出的\n    // fail-open 窗口）：路由只在第一次 `registerWebSurface` 时注册（标记位堵死重\n    // 注册），若那一刻 `connection` 还没挂载，快照下来的 `undefined` 就会让这两条\n    // 路由**永久**失去信任栅栏 —— 而宿主稍后挂上 connection 也不会重新注册。实时取\n    // 之后，栅栏一旦可用就立即生效，代价只是一次属性探测。\n    // 「降级由调用方留痕」：实时取的同时只提醒一次，避免每个请求刷一条日志。\n    const currentFence = fenceProbe(\n      () => ctx.get('connection'),\n      () => ctx.logger.warn('crossfire: connection.requestRejection is unavailable — plugin web routes run without the Host/Origin + browser-auth fence'),\n    )\n\n    if (!rpcRouteRegistered) {\n      rpcRouteRegistered = true\n      ctx.effect(() => webServer.register({\n      kind: 'exact',\n      path: RPC_ROUTE,\n      handler: async (req: IncomingMessage, res: ServerResponse) => {\n        const send = (status: number, body: unknown): void => {\n          res.writeHead(status, {\n            'content-type': 'application/json; charset=utf-8',\n            'cache-control': 'no-store',\n          })\n          res.end(JSON.stringify(body))\n        }\n        const rejection = rejectWebRequest(currentFence(), req.headers)\n        if (rejection !== undefined) {\n          send(rejection, { ok: false, error: { code: 'forbidden', message: 'connection trust check failed' } })\n          return\n        }\n        if ((req.method ?? 'GET').toUpperCase() !== 'POST') {\n          send(405, { ok: false, error: { code: 'internal', message: 'this route accepts POST only' } })\n          return\n        }\n        let body: unknown\n        try {\n          const chunks: Buffer[] = []\n          let size = 0\n          for await (const chunk of req) {\n            size += (chunk as Buffer).length\n            // 无上限的请求体等于让任何本机页面把整包塞进内存。\n            if (size > MAX_RPC_BODY_BYTES) {\n              send(413, { ok: false, error: { code: 'internal', message: 'request body too large' } })\n              return\n            }\n            chunks.push(chunk as Buffer)\n          }\n          body = JSON.parse(Buffer.concat(chunks).toString('utf8')) as unknown\n        } catch {\n          send(400, { ok: false, error: { code: 'internal', message: 'body must be JSON' } })\n          return\n        }\n        const message = body as { endpoint?: unknown; payload?: unknown } | null\n        if (message === null || typeof message !== 'object' || typeof message.endpoint !== 'string') {\n          send(400, { ok: false, error: { code: 'internal', message: 'body must be { endpoint, payload? }' } })\n          return\n        }\n        // dispatch 自身绝不抛错（见 rpc.ts）。\n        send(200, await dispatchRpc(message.endpoint, message.payload))\n      },\n      }), 'crossfire: rpc route')\n    }\n\n    if (!stateRouteRegistered) {\n      stateRouteRegistered = true\n      // 快照路由：卡片每秒轮询它。虽然是 GET（只读），仍必须过同一道栅栏 ——\n      // 这条会吐出评审正文与用户立场，不能对本机任意页面开放。\n      ctx.effect(() => webServer.register({\n        kind: 'exact',\n        path: STATE_ROUTE,\n        handler: async (req: IncomingMessage, res: ServerResponse) => {\n          const send = (status: number, payload: unknown): void => {\n            res.writeHead(status, {\n              'content-type': 'application/json; charset=utf-8',\n              'cache-control': 'no-store',\n            })\n            res.end(JSON.stringify(payload))\n          }\n          const rejection = rejectWebRequest(currentFence(), req.headers)\n          if (rejection !== undefined) {\n            send(rejection, { reviews: [], note: 'connection trust check failed' })\n            return\n          }\n          const url = new URL(req.url ?? '/', 'http://x')\n          const session = url.searchParams.get('session') ?? ''\n          const collected = await collectSnapshots(ctx, resolved.stateDir, session)\n          // 条件请求：内容未变时回 304，省掉整个响应体的传输与解析（卡片每秒轮询它）。\n          // 没有 `if-none-match` 时行为与从前逐字相同 —— 因此这是可增量上线的改动。\n          sendJsonConditional(req.headers, res, collected)\n        },\n      }), 'crossfire: snapshot route')\n    }\n  }\n  registerWebSurface()\n  ctx.on('internal/service', (serviceName) => {\n    if (WEB_SERVER_KEYS.includes(serviceName as (typeof WEB_SERVER_KEYS)[number])\n      || WORKSPACE_KEYS.includes(serviceName as (typeof WORKSPACE_KEYS)[number])) {\n      registerWebSurface()\n    }\n  })\n}\n"
    },
    {
      "path": "src/web-guard.ts",
      "content": "/**\n * Web 路由的认证栅栏（第 2 批 / P5）。\n *\n * 插件自建的两条 Web 路由（`/plugins/dsh-plugin-crossfire/rpc` 与 `.../state`）\n * 注册在宿主 `webServer` 上，而宿主 webserver 自述 \"knows no harness concepts\"、\n * handler 只有裸 `(req, res)` —— 栅栏**不会自动施加**。宿主为此专门暴露了\n * `connection.requestRejection()`，其文档原文就是：\"Apply Connection's\n * Host/Origin checks and browser authentication to another Web route\"。\n *\n * 不接它的后果是真实的：本机任意网页（DNS rebinding 后同源，或 `text/plain`\n * 简单 POST 免预检）都能命中插件路由 —— 删会议、改连线、读走全部评审内容与\n * 发言。宿主自己的 `/api` 有栅栏，插件这两条路由曾是缺口。\n *\n * @module @y9931666/dsh-plugin-crossfire/web-guard\n */\n\nimport type { IncomingMessage } from 'node:http'\n\n/** The single Connection ability this guard needs. */\nexport interface ConnectionFence {\n  requestRejection(request: { headers: IncomingMessage['headers'] }): 401 | 403 | undefined\n}\n\n/** Request-body cap for the plugin RPC route (1 MiB — same order as the host's own API). */\nexport const MAX_RPC_BODY_BYTES = 1_048_576\n\n/** Pick the fence out of a possibly-absent service (never load-gating). */\nexport function connectionFenceOf(service: unknown): ConnectionFence | undefined {\n  if (service === null || service === undefined) return undefined\n  const candidate = service as { requestRejection?: unknown }\n  if (typeof candidate.requestRejection !== 'function') return undefined\n  return candidate as ConnectionFence\n}\n\n/**\n * 建一个\"每次调用都重新取栅栏\"的探针。\n *\n * ## 为什么不是一次性解析（这是一条真实的安全修复）\n *\n * 插件路由只在第一次注册时创建，而注册带标记位、不会重来。若在**注册那一刻**把\n * `connectionFenceOf(ctx.get('connection'))` 的结果快照进闭包，那么：\n * - 那一刻 `connection` 还没挂载 → 快照到 `undefined` → 两条路由**永久**没有信任\n *   栅栏（DNS rebinding 后的同源页面、或免预检的 `text/plain` 简单 POST 都能命中）；\n * - 宿主稍后才挂上 `connection` 也不会重新注册，缺口不会被补上。\n *\n * 这就是一条 fail-open 窗口。改成每次请求实时取之后，栅栏一旦可用就立即生效，代价\n * 只是一次属性探测。抽成函数是为了能被单测直接钉住（见 `test/web-guard.test.mjs`）。\n *\n * @param getService - 返回当前的 `connection` 服务（缺席时为 `undefined`）。\n * @param onAbsent - 只在**首次**发现栅栏缺席时调用一次（用于记一条降级日志）。\n */\nexport function fenceProbe(\n  getService: () => unknown,\n  onAbsent?: () => void,\n): () => ConnectionFence | undefined {\n  let warned = false\n  return (): ConnectionFence | undefined => {\n    const fence = connectionFenceOf(getService())\n    if (fence === undefined && !warned) {\n      warned = true\n      onAbsent?.()\n    }\n    return fence\n  }\n}\n\n/**\n * Decide whether one inbound request may proceed.\n *\n * @returns the HTTP status to reject with, or `undefined` to proceed.\n *\n * A composition without the Connection service has no fence to apply and is let\n * through — the plugin must stay usable in minimal profiles. A fence that\n * *throws* is treated as a rejection: this is a security boundary, and failing\n * open would silently undo it.\n */\nexport function rejectWebRequest(\n  fence: ConnectionFence | undefined,\n  headers: IncomingMessage['headers'],\n): 401 | 403 | undefined {\n  if (fence === undefined) return undefined\n  try {\n    return fence.requestRejection({ headers })\n  } catch {\n    return 403\n  }\n}\n"
    },
    {
      "path": "src/rpc.ts",
      "content": "/**\n * Crossfire 的浏览器面：一个 `dispatch`（RPC）+ 一个快照收集器（GET）。\n *\n * ## 两条传输，同一份 dispatch\n *\n * 1. 插件自有的 web POST 路由 `/plugins/dsh-plugin-crossfire/rpc`（首选：任何带 web\n *    服务的 profile 都可达）；\n * 2. 宿主通用 connection 通道（兜底，经 `ctx.get` 懒取）。\n *\n * ## O1：卡片按钮**直推** host 状态机\n *\n * 这是 crossfire 与圆桌会议最重要的编排差异。圆桌的 UI 只能写\"用户行为队列\"，\n * 等主持人下一轮执行；针锋的按钮直接调用这里的 `crossfire/review.advance`，\n * 因此用户点\"开审\"不必等一整个模型回合。\n *\n * 代价是：**RPC 路径没有 `exec.agent`**。凡是需要父 Agent 的动作（拉起子代理）\n * 就得先按会话 id 把 Agent 找回来（`ctx.agents.get`）；找不到（会话已冷）时如实\n * 失败并让用户改用对话触发，而不是假装成功。\n *\n * ## 一条不可越界的规则\n *\n * `crossfire/defect.setStatus` **只允许人从界面调用**。它没有对应的 agent 工具，\n * 也永远不该有：表态权是这个插件存在的理由本身。\n *\n * @module dsh-plugin-crossfire/rpc\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { Agent } from '@deepseek-ai/dsh-agent'\nimport type { SessionId } from '@deepseek-ai/dsh-session'\nimport { applyCollected, collectDefects, planExperts, rosterFrom } from './engine.ts'\nimport { registerExpertChild } from './expert-events.ts'\nimport { spawnExpert } from './members.ts'\nimport { expertPersona } from './redteam.ts'\nimport { effectiveDimensions, type PreferenceStore } from './preferences.ts'\nimport {\n  buildRecheckItems,\n  countDefects,\n  exportFile,\n  exportTextFile,\n  mutateRecord,\n  newRecord,\n  readRecord,\n  readTranscriptReport,\n  setDefectStatus,\n  setRecheckVerdict,\n  writeRecord,\n} from './review.ts'\nimport { resolveDimensions } from './dimensions.ts'\nimport { renderReviewMarkdown } from './export-md.ts'\nimport type { ToolsConfig } from './tools.ts'\nimport {\n  listReviewIds,\n  newReviewId,\n  reviewLockKey,\n  stateRootOf,\n  withCrossfireLock,\n  writeTextAtomic,\n  writeTextAtomicWithBom,\n} from './state.ts'\nimport { DIMENSION_POOL, INTENSITY_SPECS, type CrossfireRecord, type Intensity, type PassSnapshot } from './types.ts'\nimport { workspaceRegistryOf } from './harness-compat.ts'\nimport type { SplitLlmLike } from './split.ts'\nimport { assertBudget, beginPass } from './budget.ts'\n\n/** 插件自有 RPC 路由（浏览器半体优先走这条）。 */\nexport const RPC_ROUTE = '/plugins/dsh-plugin-crossfire/rpc'\n\n/** 插件自有快照路由（卡片每秒轮询它）。 */\nexport const STATE_ROUTE = '/plugins/dsh-plugin-crossfire/state'\n\n/** 运行时依赖：偏好存储 + 工具/引擎共用的配置（单一来源）。 */\nexport interface CrossfireRuntime {\n  prefs: PreferenceStore\n  tools: ToolsConfig\n}\n\n/** RPC 失败包封。 */\nexport interface RpcFailure {\n  ok: false\n  error: { code: string; message: string }\n}\n\n/** RPC 结果包封（成功 / 失败二选一）。 */\nexport type RpcResult = { ok: true; value: unknown } | RpcFailure\n\nfunction ok(value: unknown): RpcResult {\n  return { ok: true, value }\n}\n\nfunction fail(message: string, code = 'internal'): RpcResult {\n  return { ok: false, error: { code, message } }\n}\n\n/** dispatch 的类型：端点名 + 载荷 → 结果包封。 */\nexport type RpcDispatch = (endpoint: string, payload: unknown) => Promise<RpcResult>\n\n/** 卡片所需的评审快照（刻意不含 workspace 绝对路径之外的任何隐私内容）。 */\nexport interface ReviewSnapshot {\n  reviewId: string\n  status: CrossfireRecord['status']\n  subjectTitle: string\n  subjectContent: string\n  subjectSource: string\n  stanceText: string\n  stanceOrigin: string\n  dimensions: string[]\n  intensity: Intensity\n  intensityLabel: string\n  reviewPass: number\n  maxReviewPass: number\n  experts: {\n    key: string\n    dimension: string\n    status: string\n    defectCount: number\n    reportCount?: number\n    /** 实际模型路由；未指定（继承主持人）时两个字段都不出现。 */\n    provider?: string\n    model?: string\n    /** 用户补充的角色定位（专家列表里可编辑）。 */\n    role?: string\n    note?: string\n  }[]\n  defects: {\n    id: string\n    expertKey: string\n    dimension: string\n    dimensionFallback?: boolean\n    content: string\n    quote?: string\n    evidence?: { kind: 'repro' | 'argument'; text: string }\n    strikesStance?: boolean\n    status: 'pending' | 'endorsed' | 'rejected'\n    rejectReason?: string\n    /** 复审核对结论；`verdict` 缺席 = 尚未判断（**不是**\"未修复\"）。 */\n    recheck?: { pass: number; verdict?: string; note?: string }\n  }[]\n  counts: { total: number; pending: number; endorsed: number; rejected: number; strikes: number }\n  budget: { maxRounds: number; maxTokens: number; usedRounds: number; usedTokens: number }\n  startedAt: number\n  updatedAt: number\n  /** 这份评审所在的状态根（客户端回传后可免去再次遍历工作区）。 */\n  stateRoot: string\n}\n\n/** 把记录收敛成卡片快照。 */\nexport function snapshotOf(record: CrossfireRecord, stateRoot: string): ReviewSnapshot {\n  return {\n    reviewId: record.reviewId,\n    status: record.status,\n    subjectTitle: record.subject.title,\n    subjectContent: record.subject.content,\n    subjectSource: record.subject.source,\n    stanceText: record.stance.text,\n    stanceOrigin: record.stance.origin,\n    dimensions: [...record.dimensions],\n    intensity: record.intensity,\n    intensityLabel: INTENSITY_SPECS[record.intensity].label,\n    reviewPass: record.reviewPass,\n    maxReviewPass: record.maxReviewPass,\n    experts: record.experts.map((expert) => ({\n      key: expert.key,\n      dimension: expert.dimension,\n      status: expert.status,\n      defectCount: expert.defectCount,\n      ...(expert.reportCount === undefined ? {} : { reportCount: expert.reportCount }),\n      // 模型路由只为了让卡片能画一个品牌块（缩写 + 品牌色）。缺失即\"继承主持人\"，\n      // 刻意不填一个默认 provider —— 那会让界面显示一个并非事实的路由。\n      ...(expert.provider === undefined ? {} : { provider: expert.provider }),\n      ...(expert.model === undefined ? {} : { model: expert.model }),\n      // 用户的补充角色定位：卡片上的\"专家列表\"要能显示与编辑它。\n      ...(expert.role === undefined ? {} : { role: expert.role }),\n      ...(expert.note === undefined ? {} : { note: expert.note }),\n    })),\n    defects: record.defects.map((defect) => ({\n      id: defect.id,\n      expertKey: defect.expertKey,\n      dimension: defect.dimension,\n      ...(defect.dimensionFallback === true ? { dimensionFallback: true } : {}),\n      content: defect.content,\n      ...(defect.quote === undefined ? {} : { quote: defect.quote }),\n      ...(defect.evidence === undefined ? {} : { evidence: defect.evidence }),\n      ...(defect.strikesStance === true ? { strikesStance: true } : {}),\n      status: defect.status,\n      ...(defect.rejectReason === undefined ? {} : { rejectReason: defect.rejectReason }),\n      ...(defect.recheck === undefined ? {} : { recheck: defect.recheck }),\n    })),\n    counts: countDefects(record),\n    budget: { ...record.budget },\n    startedAt: record.startedAt,\n    updatedAt: record.updatedAt,\n    stateRoot,\n  }\n}\n\n/* ------------------------------------------------------------------ *\n * 工作区解析（RPC 没有 exec.agent，只能靠会话 id 或遍历）\n * ------------------------------------------------------------------ */\n\n/** 会话活着时，直接从它的 Agent 拿到工作区（最精确）。 */\nfunction workspaceOfSession(ctx: Context, session: string): string | undefined {\n  if (session === '') return undefined\n  const agent = ctx.agents.get(session as SessionId)\n  if (agent === undefined) return undefined\n  const header = (agent.session as unknown as { header?: { cwd?: string } }).header\n  return header?.cwd\n}\n\n/** 会话活着时把 Agent 找回来（拉起专家需要它当 parent）。 */\nfunction agentOfSession(ctx: Context, session: string): Agent | undefined {\n  if (session === '') return undefined\n  return ctx.agents.get(session as SessionId)\n}\n\n/** 身份判定的结果。 */\nexport type ActorVerdict =\n  | { ok: true; bound: boolean }\n  | { ok: false; code: 'no-actor' | 'foreign-owner'; message: string }\n\n/**\n * 判定\"谁在操作这一场评审\"。\n *\n * ## 为什么必须是严格的（这里出过一个真实的安全缺陷）\n *\n * 会话 id 在这个插件里**同时是凭据和权限**：`load()` 用它做归属校验，\n * `review.advance` 的 attack 分支又用它换回 live Agent 去拉起专家。原先的写法把\n * 空会话当成\"跳过校验\"，于是当客户端没把 session 送进来时：\n *\n * - 归属校验整条短路（任何会话都能操作任何记录）；\n * - 而 attack 又会退回用**记录里的 owner** 换 Agent，照样把专家拉起来。\n *\n * 结果是一条能真正干活的越权通道，而且它的成功响应与合法调用完全同形 —— 验收时\n * 根本分不出来。红队在验收流程里抓到了这一点。\n *\n * 所以现在的规则是：**必须声称一个会话**。规则本身是纯函数，因此可以被测试直接\n * 钉住（`test/rpc-identity.test.mjs`），而不是只靠人工点一次按钮。\n *\n * @param ownerSessionId - 记录里的 owner（早期数据可能没有）。\n * @param actorSession - 调用方声称的会话 id（缺失时为 `''`）。\n */\nexport function judgeActor(ownerSessionId: string | undefined, actorSession: string): ActorVerdict {\n  if (actorSession === '') {\n    return {\n      ok: false,\n      code: 'no-actor',\n      message: 'this request carried no session identity — reload the page so the card can send one',\n    }\n  }\n  // 没有 owner 的是早期数据：放行但标记为未绑定，调用方可以据此提示。\n  if (ownerSessionId === undefined || ownerSessionId === '') return { ok: true, bound: false }\n  if (ownerSessionId !== actorSession) {\n    return {\n      ok: false,\n      code: 'foreign-owner',\n      message: 'this review belongs to another session',\n    }\n  }\n  return { ok: true, bound: true }\n}\n\n/** 已知的全部候选状态根（工作区注册表可用时）。 */\nfunction candidateStateRoots(ctx: Context, stateDir: string): string[] {\n  const registry = workspaceRegistryOf(ctx)\n  if (registry === undefined) return []\n  const roots: string[] = []\n  for (const workspace of registry.list()) {\n    const root = stateRootOf(workspace.path, stateDir)\n    if (!roots.includes(root)) roots.push(root)\n  }\n  return roots\n}\n\n/**\n * 定位一场评审。\n *\n * 优先用客户端回传的 `stateRoot`（一次命中，不再遍历）；否则遍历已知工作区。\n * 评审数量天然很少，所以这个遍历不是瓶颈。\n */\nasync function locateReview(\n  ctx: Context,\n  stateDir: string,\n  reviewId: string,\n  preferredRoot?: string,\n): Promise<{ stateRoot: string; record: CrossfireRecord } | undefined> {\n  const roots: string[] = []\n  if (preferredRoot !== undefined && preferredRoot !== '') roots.push(preferredRoot)\n  for (const root of candidateStateRoots(ctx, stateDir)) {\n    if (!roots.includes(root)) roots.push(root)\n  }\n  for (const root of roots) {\n    const record = await readRecord(root, reviewId)\n    if (record !== undefined) return { stateRoot: root, record }\n  }\n  return undefined\n}\n\n/** 收集全部评审快照（卡片轮询的数据源）。 */\nexport async function collectSnapshots(\n  ctx: Context,\n  stateDir: string,\n  session: string,\n): Promise<{ reviews: ReviewSnapshot[]; note?: string }> {\n  // 身份优先：先确认\"你是谁\"，再谈\"你能看什么\"。这一步必须排在工作区解析之前 ——\n  // 否则缺身份时会被报成\"没有工作区\"，把排查方向指向错误的层。\n  if (session === '') {\n    return {\n      reviews: [],\n      note: 'this request carried no session identity — reload the page so the card can send one',\n    }\n  }\n  const roots: string[] = []\n  const sessionWorkspace = workspaceOfSession(ctx, session)\n  if (sessionWorkspace !== undefined) roots.push(stateRootOf(sessionWorkspace, stateDir))\n  for (const root of candidateStateRoots(ctx, stateDir)) {\n    if (!roots.includes(root)) roots.push(root)\n  }\n  if (roots.length === 0) {\n    return {\n      reviews: [],\n      note: 'no workspace is known for this session (the session may be cold, and no workspace registry is mounted)',\n    }\n  }\n  // 空会话一律返回空集：不传身份不是\"跳过过滤\"，而是\"不知道你是谁\"。原先那种\n  // 写法在这种情况下会把**全部**评审交出去 —— 与会话 id 兼任权限凭据是同一类\n  // 问题（红队在验收里抓到过）。卡片现在总会带上 session，所以这条退化路径只在\n  // 异常时出现，而它应当是保守的那一边。（检查位置见函数开头。）\n  const reviews: ReviewSnapshot[] = []\n  for (const root of roots) {\n    for (const reviewId of await listReviewIds(root)) {\n      const record = await readRecord(root, reviewId)\n      if (record === undefined) continue\n      // 有归属的记录只回给它的 owner；没有归属的（早期数据）照常返回。\n      if (record.ownerSessionId !== undefined && record.ownerSessionId !== ''\n        && record.ownerSessionId !== session) {\n        continue\n      }\n      reviews.push(snapshotOf(record, root))\n    }\n  }\n  reviews.sort((left, right) => right.startedAt - left.startedAt)\n  return { reviews }\n}\n\n/* ------------------------------------------------------------------ *\n * dispatch\n * ------------------------------------------------------------------ */\n\n/** 注册 RPC 端点，返回可复用的 `dispatch`。 */\nexport function registerRpc(ctx: Context, runtime: CrossfireRuntime): RpcDispatch {\n  const stateDir = runtime.tools.stateDir\n\n  /** 读一个评审并校验归属。 */\n  const load = async (\n    reviewId: string,\n    session: string,\n    preferredRoot?: string,\n  ): Promise<{ stateRoot: string; record: CrossfireRecord }> => {\n    if (reviewId === '') throw new Error('reviewId must not be empty')\n    const located = await locateReview(ctx, stateDir, reviewId, preferredRoot)\n    if (located === undefined) throw new Error(`no review \"${reviewId}\"`)\n    const verdict = judgeActor(located.record.ownerSessionId, session)\n    if (!verdict.ok) throw new Error(verdict.message)\n    return located\n  }\n\n  return async (endpoint: string, payload: unknown): Promise<RpcResult> => {\n    try {\n      const body = (payload !== null && typeof payload === 'object' ? payload : {}) as Record<string, unknown>\n      const session = typeof body.session === 'string' ? body.session : ''\n      const reviewId = typeof body.reviewId === 'string' ? body.reviewId : ''\n      const preferredRoot = typeof body.stateRoot === 'string' ? body.stateRoot : undefined\n\n      switch (endpoint) {\n        /* ---------------- 偏好读写（设置页） ---------------- */\n        case 'crossfire/prefs.get': {\n          const prefs = runtime.prefs.get()\n          return ok({\n            prefs,\n            pool: [...DIMENSION_POOL],\n            dimensions: effectiveDimensions(prefs),\n            intensities: INTENSITY_SPECS,\n            stateDir,\n          })\n        }\n        case 'crossfire/prefs.set': {\n          // 身份门禁（红队评审抓出的真实缺陷）：这条分支此前**是唯一不校验会话的\n          // 写端点** —— 它写的是 `$DSH_HOME` 下的**全局**偏好文件，而 RPC 是公开\n          // HTTP 路由，于是任何能 POST 到本机端口的调用者都能改全局设置。\n          //\n          // 用 `judgeActor(undefined, session)` 而不是绑定某个 owner：偏好是全局的，\n          // 不属于哪一场评审，因此这里要的是\"**必须声称一个身份**\"（空身份一律拒），\n          // 而不是\"只有某场评审的 owner 能改\"。\n          const gate = judgeActor(undefined, session)\n          if (!gate.ok) throw new Error(gate.message)\n          if (body.patch === undefined) return fail('payload must be { patch }')\n          const next = await runtime.prefs.update(body.patch)\n          return ok({ prefs: next, dimensions: effectiveDimensions(next) })\n        }\n\n        /* ---------------- 模型目录（设置页下拉的数据源） ---------------- */\n        case 'crossfire/models.list': {\n          // 与圆桌的 `roundtable/models.list` 同源做法：向宿主的 llm 服务要 provider\n          // 与 model 目录。某个 provider 列不出模型（例如没配 key）时它仍然出现，\n          // 只是模型列表为空 —— 界面照常可用，而不是整个下拉空掉。\n          //\n          // **目录源必须是两条而不是一条**（红队评审抓出的真实缺陷）：宿主的\n          // `LlmFace` 把\"模型目录\"定义为 `listProviders()`（已注册/live）与\n          // `listConfigurableProviders()`（声明但休眠）的**并集**\n          // （`@deepseek-ai/dsh-llm` 的 `LlmConfigurableProvider` 文档明说\n          // \"whether or not the route is currently registered\"）。只取前者会让\n          // 下拉的选项集合严格窄于它所取代的文本框：未配置的 provider 在针锋里\n          // 根本选不到，而宿主的 Models 页列得出来。\n          const llm = ctx.get('llm') as\n            | {\n                listProviders(): { id: string; name: string }[]\n                listConfigurableProviders?(): { provider: string; displayName: string }[]\n                listModels(provider: string): Promise<{ id: string; name: string }[]>\n              }\n            | undefined\n          if (llm === undefined) return ok({ providers: [] })\n\n          const merged = new Map<string, { id: string; name: string; active: boolean }>()\n          for (const provider of llm.listProviders()) {\n            merged.set(provider.id, { id: provider.id, name: provider.name, active: true })\n          }\n          // 可选探测：老宿主没有这个方法时保持\"只有 live provider\"的旧行为，\n          // 而不是把整条端点打挂（探测式降级，不写进 inject 门禁）。\n          if (typeof llm.listConfigurableProviders === 'function') {\n            let declared: { provider: string; displayName: string }[] = []\n            try {\n              declared = llm.listConfigurableProviders()\n            } catch {\n              declared = []\n            }\n            for (const provider of declared) {\n              if (merged.has(provider.provider)) continue\n              merged.set(provider.provider, { id: provider.provider, name: provider.displayName, active: false })\n            }\n          }\n          // active 的排前面：下拉里\"能直接用的\"应该先出现，休眠项排后并以 active=false\n          // 标记（客户端据此禁用并提示\"需先在宿主配置\"），排序保证同一份输入顺序稳定。\n          const providers: { id: string; name: string; models: { id: string; name: string }[]; active: boolean }[] = []\n          for (const entry of [...merged.values()].sort((left, right) => {\n            if (left.active !== right.active) return left.active ? -1 : 1\n            return left.id < right.id ? -1 : left.id > right.id ? 1 : 0\n          })) {\n            let models: { id: string; name: string }[] = []\n            // 休眠 provider 不列举模型：它没有活路由，列举只会失败或被折叠成空数组，\n            // 那正是\"看起来能选、选了不生效\"的来源。\n            if (entry.active) {\n              try {\n                models = (await llm.listModels(entry.id)).map((model) => ({ id: model.id, name: model.name }))\n              } catch {\n                models = []\n              }\n            }\n            providers.push({ id: entry.id, name: entry.name, models, active: entry.active })\n          }\n          return ok({ providers })\n        }\n\n        /* ---------------- 快照（卡片轮询） ---------------- */\n        case 'crossfire/reviews.list': {\n          const collected = await collectSnapshots(ctx, stateDir, session)\n          return ok(collected)\n        }\n        case 'crossfire/review.get': {\n          const located = await load(reviewId, session, preferredRoot)\n          return ok({ review: snapshotOf(located.record, located.stateRoot) })\n        }\n\n        /* ---------------- 表态（**只允许人从界面调用**） ---------------- */\n        case 'crossfire/defect.setStatus': {\n          const defectId = typeof body.defectId === 'string' ? body.defectId : ''\n          if (defectId === '') return fail('payload must be { reviewId, defectId, status }')\n          const status = body.status\n          if (status !== 'pending' && status !== 'endorsed' && status !== 'rejected') {\n            return fail('status must be \"pending\" | \"endorsed\" | \"rejected\"')\n          }\n          const rejectReason = typeof body.rejectReason === 'string' ? body.rejectReason : ''\n          if (status === 'rejected' && rejectReason.trim() === '') {\n            return fail('rejecting a defect requires a non-empty reject_reason (驳回必填理由)')\n          }\n          const located = await load(reviewId, session, preferredRoot)\n          const changed = await setDefectStatus(located.stateRoot, reviewId, defectId, status, rejectReason)\n          return ok({ changed, status })\n        }\n        /* ---------------- 专家原提示词（只读） ----------------\n         *\n         * 用户反馈：\"红队专家那里，我无法看见它的原本提示词是什么\"。\n         *\n         * ## \"原提示词\"必须是**真的那一份**（红队抓出的缺陷，两处成因都修了）\n         *\n         * 1. **优先返回落盘的那一份**（`expert.persona`，由 `members.ts` 在\n         *    `startContinuable` 成功之后写入，与真正下发给子代理的是**同一次调用的\n         *    返回值**）。这是根本修法：persona 是从记录现场重建的，而攻击开始后用户\n         *    还能改 role、改立场 —— 已下发的那一份不会变，现场重建出来的却是新文本。\n         *    拿新文本当\"原文\"展示，是一句看起来精确、实际是伪造的原文。\n         * 2. **只有旧记录（缺该字段）才现场重建**，且重建必须与真实下发**同源**：\n         *    维度取 `record.dimensions`（本次评审采用的维度）而不是\n         *    `record.experts.map(...)`（那已经按上限截断、还可能重复），条数取运行时\n         *    的 `defaults.expertMaxOpinions`（设置页可调）而不是硬编码的 3 ——\n         *    `members.ts` 下发的正是这两个来源。\n         *\n         * 只读：不写任何状态，也不参与路由。\n         */\n        case 'crossfire/expert.prompt': {\n          const expertKey = typeof body.expertKey === 'string' ? body.expertKey : ''\n          if (expertKey === '') return fail('payload must be { reviewId, expertKey }')\n          const located = await load(reviewId, session, preferredRoot)\n          const expert = located.record.experts.find((item) => item.key === expertKey)\n          if (expert === undefined) return fail(`no expert \"${expertKey}\" in this review`)\n          if (expert.persona !== undefined && expert.persona !== '') {\n            return ok({ expertKey, dimension: expert.dimension, persona: expert.persona, rebuilt: false })\n          }\n          const persona = expertPersona({\n            reviewId: located.record.reviewId,\n            dimension: expert.dimension,\n            title: located.record.subject.title,\n            subject: located.record.subject.content,\n            stance: located.record.stance.text,\n            dimensions: located.record.dimensions,\n            maxOpinions: runtime.tools.getDefaults().expertMaxOpinions,\n            ...(expert.role === undefined ? {} : { role: expert.role }),\n          })\n          return ok({ expertKey, dimension: expert.dimension, persona, rebuilt: true })\n        }\n\n        /* ---------------- 专家角色定位（卡片上的专家列表可直接编辑） ----------------\n         *\n         * 用户诉求：\"我无法对专家列表的专家提示词进行修改\"。角色定位进 persona 的\n         * 「你的角色定位」段（见 redteam.ts），那一段带不可覆盖的声明 —— 用户能收窄\n         * 专长，但改不掉\"只读、不产出方案\"这些硬约束。\n         *\n         * 它与设置页的阵容成员 `role` 是**两条来源**：阵容是\"开审前的默认值\"，这里\n         * 是\"对某一场评审的就地调整\"。后者优先级更高，因为它写在记录里。\n         */\n        case 'crossfire/expert.setRole': {\n          const expertKey = typeof body.expertKey === 'string' ? body.expertKey : ''\n          if (expertKey === '') return fail('payload must be { reviewId, expertKey, role }')\n          if (typeof body.role !== 'string') return fail('payload must carry a string `role`')\n          const role = body.role.trim().slice(0, 2000)\n          const located = await load(reviewId, session, preferredRoot)\n          const outcome = await mutateRecord(located.stateRoot, reviewId, (current) => {\n            const expert = current.experts.find((item) => item.key === expertKey)\n            if (expert === undefined) return { found: false, changed: false }\n            const before = expert.role ?? ''\n            if (before === role) return { found: true, changed: false }\n            // 空串 = 清除该定位（回到\"只有维度\"的原始 persona），而不是留一个空字段。\n            if (role === '') delete expert.role\n            else expert.role = role\n            return { found: true, changed: true }\n          })\n          if (outcome === undefined) return fail(`no review \"${reviewId}\"`)\n          if (!outcome.found) return fail(`no expert \"${expertKey}\" in this review`)\n          return ok({ changed: outcome.changed })\n        }\n        case 'crossfire/recheck.setVerdict': {          const defectId = typeof body.defectId === 'string' ? body.defectId : ''\n          const verdict = body.verdict\n          if (defectId === '' || (verdict !== 'fixed' && verdict !== 'unfixed' && verdict !== 'partial')) {\n            return fail('payload must be { reviewId, defectId, verdict: fixed | unfixed | partial }')\n          }\n          const located = await load(reviewId, session, preferredRoot)\n          const note = typeof body.note === 'string' ? body.note : ''\n          const changed = await setRecheckVerdict(located.stateRoot, reviewId, defectId, verdict, note)\n          return ok({ changed })\n        }\n\n        /* ---------------- 立场（批 4 的 UI 用，端点先就位） ---------------- */\n        case 'crossfire/stance.set': {\n          const text = typeof body.text === 'string' ? body.text.trim().slice(0, 2000) : ''\n          const located = await load(reviewId, session, preferredRoot)\n          await mutateRecord(located.stateRoot, reviewId, (record) => {\n            // 人改过之后 origin 变 edited：自动提炼**不再覆盖**它（批 4）。\n            record.stance = {\n              text,\n              origin: 'edited',\n              ...(record.stance.distilledAt === undefined ? {} : { distilledAt: record.stance.distilledAt }),\n              updatedAt: Date.now(),\n            }\n            return undefined\n          })\n          return ok({ saved: true })\n        }\n\n        /* ---------------- 从界面直接开一场评审 ---------------- */\n        case 'crossfire/review.open': {\n          // 刻意**不转发** `body.workspace`：写入根只能由会话推导（见\n          // `openReviewFromRpc` 的注释 —— 那是红队抓出的一条无人使用的逃逸通道）。\n          return await openReviewFromRpc(ctx, runtime, {\n            session,\n            title: typeof body.title === 'string' ? body.title : '',\n            content: typeof body.content === 'string' ? body.content : '',\n            ...(body.dimensions === undefined ? {} : { dimensions: body.dimensions }),\n            ...(body.intensity === undefined ? {} : { intensity: body.intensity }),\n            ...(typeof body.stance === 'string' ? { stance: body.stance } : {}),\n          })\n        }\n\n        /* ---------------- 导出（卡片上的下载按钮） ---------------- */\n        case 'crossfire/review.export': {\n          const located = await load(reviewId, session, preferredRoot)\n          // 导出是收尾路径：预算熔断时也必须可用。\n          assertBudget(located.record, { allowMuted: true })\n          const markdown = renderReviewMarkdown(located.record, countDefects(located.record))\n          const path = exportFile(located.stateRoot, reviewId)\n          await writeTextAtomic(path, markdown)\n          // 人读副本：`.txt` + UTF-8 BOM，双击直接进记事本（.md 常被别的程序抢走）。\n          let textPath: string\n          try {\n            textPath = exportTextFile(located.stateRoot, reviewId)\n            await writeTextAtomicWithBom(textPath, markdown)\n          } catch {\n            // 副本写不成不影响导出本身：`.md` 已经在盘上了。\n            textPath = ''\n          }\n          return ok({ path, textPath, bytes: Buffer.byteLength(markdown, 'utf8'), markdown })\n        }\n\n        /* ---------------- O1 直推：推进状态机 ---------------- */\n        case 'crossfire/review.advance': {\n          const step = body.step\n          if (step !== 'attack' && step !== 'collect' && step !== 'finish' && step !== 'recheck') {\n            return fail('step must be \"attack\" | \"collect\" | \"finish\" | \"recheck\"')\n          }\n          const located = await load(reviewId, session, preferredRoot)\n          return await advance(ctx, runtime, located, step, body, session)\n        }\n\n        default:\n          return fail(`unknown endpoint \"${endpoint}\"`)\n      }\n    } catch (error: unknown) {\n      // dispatch 绝不抛错：调用方拿到的永远是一个结构化的失败。\n      const message = error instanceof Error ? error.message : String(error)\n      ctx.logger.warn(`crossfire: rpc \"${endpoint}\" failed`, error)\n      return fail(message)\n    }\n  }\n}\n\n/* ------------------------------------------------------------------ *\n * 状态机直推\n * ------------------------------------------------------------------ */\n\n/**\n * 卡片按钮推进状态机。\n *\n * 四个步骤各自的门禁与工具端**完全一致**（同一套 review/engine 函数），差别只在\n * \"谁是被授权者\"：工具用 `exec.agent`，这里用会话 id 换回来的 Agent。\n */\nasync function advance(\n  ctx: Context,\n  runtime: CrossfireRuntime,\n  located: { stateRoot: string; record: CrossfireRecord },\n  step: 'attack' | 'collect' | 'finish' | 'recheck',\n  body: Record<string, unknown>,\n  session: string,\n): Promise<RpcResult> {\n  const { stateRoot } = located\n  const reviewId = located.record.reviewId\n  const defaults = runtime.tools.getDefaults()\n\n  if (step === 'attack') {\n    // 拉起子代理必须有父 Agent。身份已由 load() 严格校验过，这里直接用调用方声称\n    // 的会话 —— **刻意不退回记录里的 owner**：那把凭据同时是权限，退回它等于给空\n    // 会话开一条能真正拉起专家的越权通道（红队在验收流程里抓到的真实缺陷）。\n    const agent = agentOfSession(ctx, session)\n    if (agent === undefined) {\n      return fail(\n        'the session that owns this review is not live right now, so Crossfire cannot send in the red team '\n        + 'from the card — ask in the conversation instead (crossfire_attack)',\n        'session-offline',\n      )\n    }\n\n    // 状态门禁 + 规划 + spawn + 写回**全部在同一个临界区里**（A4 + A6）。\n    //\n    // 此前只有\"门禁 + 规划\"在锁内，spawn 与写回在锁外，于是存在一个真实的并发窗口：\n    // 两个请求都能通过门禁（各自看到 status=attacking、没有任何 running 专家），各自\n    // 拉起一批专家，而第二批的写回把第一批的 experts 整批覆盖 —— 第一批已经真的跑起来\n    // 了（正花着用户的 token），却再没有任何人跟踪它们的 childId，收集阶段也拿不到它们\n    // 的产出。把 spawn 纳进同一个临界区后，第二个请求拿到锁时读到的是第一批的最终状态，\n    // 直接命中下面那条\"已有在跑的专家\"判据。\n    //\n    // 代价（刻意的）：拉起 N 位专家期间，同一场评审的其它写操作会排队。同一场评审的写\n    // 本就该串行，这里只是把这条不变量贯彻到底 —— 用\"排队等待\"换\"不再产生孤儿专家\"。\n    return await withCrossfireLock(reviewLockKey(stateRoot, reviewId), async () => {\n      const current = await readRecord(stateRoot, reviewId)\n      if (current === undefined) return fail(`no review \"${reviewId}\"`)\n      // 只允许 draft 与 attacking：\n      // - draft 是卡片上那个攻击按钮**唯一可见**的状态；\n      // - attacking 是复审轮（recheck 之后）的起点。\n      // **刻意不含 settled**：对已定稿的评审直接重新攻击会绕过复审流程（不开新轮、\n      // 不清缺陷），而卡片在 settled 上根本没有攻击按钮 —— 放行它只会造出一条谁也\n      // 点不到、却能被直接调用的路径。\n      if (current.status !== 'draft' && current.status !== 'attacking') {\n        return fail(\n          `review \"${reviewId}\" is \"${current.status}\" — cannot send in the red team now `\n          + '(call crossfire_recheck to open a new pass on a settled review)',\n        )\n      }\n      // A4 的第二道判据：这一场评审**已经有一批专家在跑**。\n      //\n      // 为什么不能靠\"把 attacking 从允许列表里删掉\"来解决重复启动：`attacking` 必须\n      // 仍是合法起点 —— 复审轮（settled → recheck → attacking）正是置成 attacking 之后\n      // 才重新开打的，删掉它等于复审永远打不起来。所以判据只能是\"记录里有没有 running\n      // 的专家\"：\n      // - 有 → 这一批还没结束，拒绝重复启动。放行会**覆盖掉正在跑的 childId**，那些\n      //   专家仍在消耗 token 产出，却再也归不了账；\n      // - 没有（全部 done/silent/failed，或刚开轮 experts 为空）→ 允许启动。\n      //   \"上一批全部 failed 之后用户重试\"走的正是这条路（见 test/rpc-dispatch.test.mjs）。\n      const running = current.experts.filter((expert) => expert.status === 'running')\n      if (running.length > 0) {\n        return fail(\n          `experts are already running for this review (${running.map((expert) => expert.key).join(', ')}) — `\n          + 'wait for them to report, or collect what they have already submitted',\n        )\n      }\n      // 阵容来源：用户偏好里的**第一套阵容**（没有阵容时退回角色预设，按顺序平铺）。\n      // 这一步修的是红队抓出的\"预设只写不读\"：此前 `rolePresets`/`squads` 在主流程\n      // 零消费点，`ExpertPersonaInput` 没有 role 字段，`expert.provider`/`expert.model`\n      // 也永远缺席 —— 设置页因此是个存了不用的仓库。\n      const prefs = runtime.prefs.get()\n      const roster = rosterFrom({\n        squads: prefs.squads.map((squad) => ({\n          id: squad.id,\n          members: squad.members.map((member) => ({\n            key: member.key,\n            ...(member.role === undefined ? {} : { role: member.role }),\n            ...(member.provider === undefined ? {} : { provider: member.provider }),\n            ...(member.model === undefined ? {} : { model: member.model }),\n          })),\n        })),\n        rolePresets: prefs.rolePresets.map((preset) => ({\n          key: preset.name,\n          ...(preset.role === undefined ? {} : { role: preset.role }),\n          ...(preset.provider === undefined ? {} : { provider: preset.provider }),\n          ...(preset.model === undefined ? {} : { model: preset.model }),\n        })),\n      })\n      const experts = planExperts(current, runtime.tools.maxExperts, roster)\n      const isRecheck = current.reviewPass > 1 && current.history.length > 0\n      if (isRecheck && current.defects.length === 0) current.defects = buildRecheckItems(current)\n      current.experts = experts\n      current.status = 'attacking'\n      // 先落一次盘再拉起：卡片立刻能看到 attacking + pending，而不必等所有子代理都\n      // 起来（真实拉起是十秒级的），锁内的记录也因此始终与盘上一致。\n      await writeRecord(stateRoot, current)\n\n      const failures: string[] = []\n      for (const expert of experts) {\n        const controller = new AbortController()\n        try {\n          const childId = await spawnExpert(\n            ctx,\n            {\n              provider: runtime.tools.memberProvider,\n              ...(runtime.tools.memberMaxDepth === undefined ? {} : { maxDepth: runtime.tools.memberMaxDepth }),\n              // 专家继承主持人时的生效路由：写回记录后卡片才能把\"继承\"画成真实品牌块\n              // （否则头像永远是中性灰 `?`，这条是用户反馈的缺陷）。\n              ...(runtime.tools.defaultProvider === undefined ? {} : { defaultProvider: runtime.tools.defaultProvider }),\n              ...(runtime.tools.defaultModel === undefined ? {} : { defaultModel: runtime.tools.defaultModel }),\n            },\n            current,\n            expert,\n            agent,\n            controller.signal,\n            { maxTokens: defaults.expertMaxTokens, maxOpinions: defaults.expertMaxOpinions },\n          )\n          expert.childId = childId\n          expert.status = 'running'\n          registerExpertChild(childId, { stateRoot, reviewId })\n        } catch (error: unknown) {\n          expert.status = 'failed'\n          expert.note = error instanceof Error ? error.message : String(error)\n          failures.push(`${expert.key}: ${expert.note}`)\n        }\n      }\n      // 写回的是**同一批对象**（`current.experts` 就是 `experts`），所以 childId、\n      // status、以及 spawnExpert 落下的 persona 一并持久化。\n      current.experts = experts\n      await writeRecord(stateRoot, current)\n      return ok({\n        spawned: experts.filter((expert) => expert.status === 'running').length,\n        failed: failures.length,\n        failures,\n      })\n    })\n  }\n\n  if (step === 'collect') {\n    const llm = ctx.get('llm') as SplitLlmLike | undefined\n    // 状态门禁 + 读转录 + 拆分 + 合并写回**全部在同一个临界区里**（A2 + A6）。\n    //\n    // 此前是\"锁外读快照 → 锁外拆分 → 锁内纯拼接\"：两次点击（或两个并发请求）都基于\n    // 同一份旧快照拆分，第二批的 `added` 又被拼进 defects —— 裁决面上于是出现一条条\n    // 一模一样的重复缺陷，用户得对同一条缺陷点两次驳回、理由写两遍。现在整段串行化：\n    // 第二次进来时锁内读到的已经是第一批的结果，`collectDefects` 的 `utteranceId`\n    // 幂等键直接命中，`applyCollected` 的 `id` 幂等键是第二道闸。\n    //\n    // 代价（刻意的）：拆分走 LLM 是十秒级的，持锁期间同一场评审的其它写操作会排队。\n    // 同一场评审的写本就该串行 —— 用\"排队\"换\"列表里不再出现重复项\"。\n    return await withCrossfireLock(reviewLockKey(stateRoot, reviewId), async () => {\n      const current = await readRecord(stateRoot, reviewId)\n      if (current === undefined) return fail(`no review \"${reviewId}\"`)\n      if (current.status !== 'attacking' && current.status !== 'judging') {\n        return fail(`review \"${reviewId}\" is \"${current.status}\" — cannot collect now`)\n      }\n      const transcript = await readTranscriptReport(stateRoot, reviewId)\n      // 拆分阶段的有界并发上限住在 `reviewSplit` 里（engine 单点读取），\n      // 因此这里不必单独传参 —— 工具侧读同一份配置，两边行为一致。\n      const outcome = await collectDefects({\n        record: current,\n        transcript: transcript.items,\n        malformed: transcript.malformed,\n        llm,\n        splitConfig: runtime.tools.reviewSplit,\n      })\n      // `collected` 报的是**真正追加的条数**，不是 `added.length`：并发的第二次调用\n      // 一条都不该新增，报 added.length 会让用户看到\"新增 3 条\"而列表里一条没变。\n      const appended = applyCollected(current, outcome.added)\n      current.status = 'judging'\n      await writeRecord(stateRoot, current)\n      return ok({\n        collected: appended,\n        droppedDuplicates: outcome.droppedDuplicates,\n        skippedNoise: outcome.skippedNoise,\n        splitAttempts: outcome.splitAttempts,\n        recheckRound: current.reviewPass > 1 && current.history.length > 0,\n      })\n    })\n  }\n\n  if (step === 'finish') {\n    const summary = typeof body.summary === 'string' ? body.summary.trim() : ''\n    // 状态门禁 + 追加历史 + 置 settled 全在同一个临界区里（A6）。\n    //\n    // 此前门禁在锁外、锁内的 `mutateRecord` 回调又不重校状态，于是并发两次 finish\n    // 会各自追加一条**同一个 pass** 的 history 快照 —— \"这一轮定稿\"在历史里出现两次，\n    // 复审时同一批旧账被核对两遍。\n    return await withCrossfireLock(reviewLockKey(stateRoot, reviewId), async () => {\n      const current = await readRecord(stateRoot, reviewId)\n      if (current === undefined) return fail(`no review \"${reviewId}\"`)\n      if (current.status !== 'judging' && current.status !== 'attacking' && current.status !== 'settled') {\n        return fail(`review \"${reviewId}\" is \"${current.status}\" — cannot settle now`)\n      }\n      const snapshot: PassSnapshot = {\n        pass: current.reviewPass,\n        subject: current.subject.content,\n        stanceText: current.stance.text,\n        dimensions: [...current.dimensions],\n        intensity: current.intensity,\n        defects: current.defects.map((defect) => ({ ...defect })),\n        finishedAt: Date.now(),\n        ...(summary === '' ? {} : { revisedSummary: summary }),\n      }\n      // **同一 pass 在 history 里只能有一条**：已存在就原地更新它。重复定稿应当是一次\n      // 幂等的更新（用户改完表态又点一次定稿是合法操作），而不是又叠一份快照 ——\n      // 叠出来的历史会让复审把同一批旧账核对两遍，且先写的那份永远是最旧的。\n      const existing = current.history.findIndex((item) => item.pass === current.reviewPass)\n      if (existing >= 0) current.history[existing] = snapshot\n      else current.history = [...current.history, snapshot]\n      current.status = 'settled'\n      current.settledAt = Date.now()\n      await writeRecord(stateRoot, current)\n      return ok({ settled: true, counts: countDefects(current) })\n    })\n  }\n\n  // step === 'recheck'\n  const approved = body.approved === true\n  // 状态门禁 + 轮次上限判定 + 开轮写回全在同一个临界区里（A6）：并发两次 recheck\n  // 此前会各自基于同一份旧快照 `+1`，把同一批旧账开成两轮（第二次的 defects 又被\n  // 覆盖一遍，预算 usedRounds 却被扣了两次）。\n  return await withCrossfireLock(reviewLockKey(stateRoot, reviewId), async () => {\n    const current = await readRecord(stateRoot, reviewId)\n    if (current === undefined) return fail(`no review \"${reviewId}\"`)\n    if (current.status !== 'settled') {\n      return fail(`review \"${reviewId}\" is \"${current.status}\" — only a settled review can be re-checked`)\n    }\n    const nextPass = current.reviewPass + 1\n    if (nextPass > current.maxReviewPass && !approved) {\n      return fail(\n        `re-review cap reached (pass ${nextPass} > max ${current.maxReviewPass}) — the user must approve continuing`,\n        'cap-reached',\n      )\n    }\n    const items = buildRecheckItems(current)\n    current.reviewPass = beginPass(current)\n    if (approved) current.maxReviewPass = Math.max(current.maxReviewPass, current.reviewPass)\n    current.defects = items\n    current.experts = []\n    current.status = 'attacking'\n    current.settledAt = undefined\n    await writeRecord(stateRoot, current)\n    return ok({ reviewPass: current.reviewPass, recheckItems: items.length })\n  })\n}\n\n/* ------------------------------------------------------------------ *\n * 供批 4 复用：新建评审（RPC 侧）\n * ------------------------------------------------------------------ */\n\n/**\n * 从界面直接开一场评审。\n *\n * 与 `crossfire_open` 工具同源，区别只是工作区来自会话 id 而不是 `exec.agent`。\n */\nexport async function openReviewFromRpc(\n  ctx: Context,\n  runtime: CrossfireRuntime,\n  input: {\n    session: string\n    title: string\n    content: string\n    dimensions?: unknown\n    intensity?: unknown\n    stance?: string\n  },\n): Promise<RpcResult> {\n  // 新建同样必须声称身份：否则会产出一场 `ownerSessionId` 为空的\"无主评审\"，\n  // 而按归属规则，无主评审对任何会话都开放。\n  if (input.session === '') {\n    return fail('this request carried no session identity — reload the page so the card can send one', 'no-actor')\n  }\n  // 工作区**只由会话推导**，刻意不接受调用方传入（红队评审抓出的真实缺陷）：\n  // 此前 dispatch 会把请求体里的 `workspace` 原样传进来，于是任何能 POST 到本机\n  // 端口的调用者都能指定任意目录当写入根，在该目录下创建 `.crossfire/crossfire/x-*`。\n  // 而卡片**从不**发送这个字段（`src/client` 全目录检索 `workspace` 只命中一句文案），\n  // 所以这条通道没有任何正当用法 —— 没有调用者的写权限入口就是纯粹的逃逸面。\n  //\n  // 以后若真要做\"对任意目录开审\"，正确做法是**先把该目录注册成工作区**、再从这里\n  // 经 `workspaceRegistryOf(ctx)` 查出来，而不是把路径本身交给调用方。\n  const workspace = workspaceOfSession(ctx, input.session)\n  if (workspace === undefined || workspace === '') {\n    return fail('cannot determine the workspace for this session', 'no-workspace')\n  }\n  const defaults = runtime.tools.getDefaults()\n  const content = input.content.trim()\n  if (content === '') return fail('content must not be empty')\n  const intensity: Intensity = input.intensity === 'quick' || input.intensity === 'deep' ? input.intensity : defaults.intensity\n  const stateRoot = stateRootOf(workspace, runtime.tools.stateDir)\n  const reviewId = newReviewId()\n  const record = newRecord({\n    reviewId,\n    title: input.title.trim() || content.slice(0, 40),\n    content,\n    source: 'manual',\n    dimensions: resolveDimensions(input.dimensions, defaults.customDimensions),\n    intensity,\n    stanceText: input.stance ?? '',\n    maxRounds: defaults.maxRounds,\n    maxTokens: defaults.maxTokens,\n    ownerSessionId: input.session,\n  })\n  await withCrossfireLock(reviewLockKey(stateRoot, reviewId), async () => {\n    await writeRecord(stateRoot, record)\n  })\n  return ok({ review: snapshotOf(record, stateRoot) })\n}\n\n/** 导出路径（批 4 的下载按钮用）。 */\nexport { exportFile }\n"
